def lcs(s1, s2):
    if len(s1) < len(s2):
        s1, s2 = s2, s1
    dp = [0] * (len(s2) + 1)
    for c1 in s1:
        prev = 0
        for j, c2 in enumerate(s2, 1):
            temp = dp[j]
            if c1 == c2:
                dp[j] = prev + 1
            else:
                dp[j] = max(dp[j], dp[j - 1])
            prev = temp
    return dp[len(s2)]
```

